sys_security_acl.script:
// ACL Script for x_kp101_kpmg_res_0_resource_profile table
// Purpose: Allow write if the current user matches the resource name; otherwise, deny

(function() {
// Server-side ACL script

// Explicit error handling for missing record or field
if (!current || !current.isValidRecord()) {
	gs.info('ACL: Invalid or missing current record for resource profile', 'x_kp101_kpmg_res_0_resource_profile');
	return false;
}

// Get the resource name from the record
var resourceName = current.resource_name.name;
if (!resourceName) {
	gs.info('ACL: resource_name field is empty on resource profile ' + current.getUniqueValue(), 'x_kp101_kpmg_res_0_resource_profile');
	return false;
}

// Compare with current user's display name (case-insensitive)
var userDisplayName = gs.getUserDisplayName();
if (!userDisplayName) {
	gs.info('ACL: Unable to retrieve current user display name', 'x_kp101_kpmg_res_0_resource_profile');
	return false;
}

// Validate user roles
	if(gs.getUser().isMemberOf('Resource Hub Managers') ||gs.getUser().isMemberOf('Resource Hub Admins')){
		gs.info("USER IS MEMBER OF GROUP");
		return true;
	}

	// Trim and compare names for robustness
if (resourceName.toString().trim().toLowerCase() === userDisplayName.trim().toLowerCase()) {
	gs.info("USER SAME AS RESOURCE NAME")
	// Allow write
	return true;
}





// Deny if not matching
return false;
})();
